// This module handles order total calculation stuff
// It computes the totals for orders and applies discounts as needed

import { Order, Item, Result } from './types';

// Step 1: validate the items in the order
function validateItems(items: any): boolean {
  // check that items is valid
  if (items == null) {
    return false;
  }
  if (!Array.isArray(items)) {
    return false;
  }
  // loop through items and validate each one
  for (let index = 0; index < items.length; index++) {
    const currentItem = items[index];
    if (typeof currentItem !== 'object') {
      return false;
    }
    if (currentItem.price == undefined) {
      return false;
    }
    if (typeof currentItem.price !== 'number') {
      return false;
    }
    if (currentItem.qty == undefined) {
      return false;
    }
  }
  return true;
}

// helper to round money values to 2 decimal places
function roundMoney(value: number): number {
  // rounds to 2 decimals
  return Math.round(value * 100) / 100;
}

// computes line total for a single item
function computeLineTotal(item: any): number {
  const price: number = (item as any).price;
  const qty: number = (item as any).qty as number;
  const lineTotal = price * qty;
  return roundMoney(lineTotal);
}

// wraps computeLineTotal with extra safety
function safeLineTotal(item: Item): number {
  try {
    return computeLineTotal(item);
  } catch (e) {
    return 0;
  }
}

export function computeTotal(order: Order): number {
  // Step 2: compute the total
  let total = 0;
  const items = (order as any).items as any[];
  if (!validateItems(items)) {
    return 0;
  }
  for (let index = 0; index < items.length; index++) {
    total = total + safeLineTotal(items[index]);
  }
  // Step 3: round and return
  return roundMoney(total);
}

export function applyDiscount(total: number, code: string | null | undefined): number {
  // applies a discount code to the total
  let result = total;
  if (code !== null && code !== undefined && code !== '') {
    if (code === 'SAVE10') {
      result = result * 0.9;
    } else if (code === 'SAVE20') {
      result = result * 0.8;
    } else if (code === 'HALFOFF') {
      result = result * 0.5;
    } else {
      // unknown code: no discount
      result = result * 1;
    }
  }
  return roundMoney(result);
}

// builds a summary object with the total, item count, and discount info
export function summarize(order: Order, code?: string | null): Result {
  const total = computeTotal(order);
  const discounted = applyDiscount(total, code);
  const summary = {
    status: 'success',
    ok: true,
    total: total,
    discounted: discounted,
    itemCount: (order as any).items.length,
    savings: roundMoney(total - discounted),
  };
  return summary as unknown as Result;
}

